def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    bg = background(g)
    vals = [c for c in np.unique(g) if c != bg]
    L = vals[0]
    d = dividers(g)
    cy = [y for y, c in d["rows"] if c == L][0]
    cx = [x for x, c in d["cols"] if c == L][0]

    out = g.copy()
    # stage 1: erase the original L line to background
    for y in range(H):
        for x in range(W):
            if min(abs(y - cy), abs(x - cx)) == 0:
                out[y, x] = bg
    emit(out, "Erase the original L-shaped line along the edges, turning it into background.")

    # stage 2: draw the L one step inward
    for y in range(H):
        for x in range(W):
            a, b = abs(y - cy), abs(x - cx)
            if min(a, b) == 1 and a != b:
                out[y, x] = L
    emit(out, "Redraw the L line one step inward from the corner, in the line colour.")

    # stage 3: fill the interior with 8
    for y in range(H):
        for x in range(W):
            a, b = abs(y - cy), abs(x - cx)
            if min(a, b) >= 2 and a != b:
                out[y, x] = 8
    emit(out, "Fill the region inside the new L with colour 8.")

    # stage 4: the diagonal from the corner
    for y in range(H):
        for x in range(W):
            a, b = abs(y - cy), abs(x - cx)
            if a == b:
                out[y, x] = 8 if a <= 1 else bg
    emit(out, "Draw the corner diagonal: 8 at the old and new corners, background along the rest.")
    return out
